import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    private static final int PRIME_BITS = 29;
    private static final int ROW_BOUND_BITS = 10;
    // the 35 smallest primes above 10^9, between 2^29 and 2^30; generated by 1914_matrix_table.py
    private static final long[] PRIMES = {
        1000000007, 1000000009, 1000000021, 1000000033, 1000000087,
    1000000093, 1000000097, 1000000103, 1000000123, 1000000181,
    1000000207, 1000000223, 1000000241, 1000000271, 1000000289,
    1000000297, 1000000321, 1000000349, 1000000363, 1000000403,
    1000000409, 1000000411, 1000000427, 1000000433, 1000000439,
    1000000447, 1000000453, 1000000459, 1000000483, 1000000513,
    1000000531, 1000000579, 1000000607, 1000000613, 1000000637
    };

    private static long power(long value, long exponent, long modulus) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = result * value % modulus;
            }
            value = value * value % modulus;
            exponent >>= 1;
        }
        return result;
    }

    private static long determinantModulo(long[][] matrix, long modulus) {
        int size = matrix.length;
        long[][] values = new long[size][size];
        for (int row = 0; row < size; row++) {
            for (int column = 0; column < size; column++) {
                values[row][column] = (matrix[row][column] % modulus + modulus) % modulus;
            }
        }
        long determinant = 1;
        for (int column = 0; column < size; column++) {
            int pivot = column;
            while (pivot < size && values[pivot][column] == 0) {
                pivot++;
            }
            if (pivot == size) {
                return 0;
            }
            if (pivot != column) {
                long[] temporary = values[pivot];
                values[pivot] = values[column];
                values[column] = temporary;
                determinant = modulus - determinant;
            }
            long[] pivotLine = values[column];
            long pivotValue = pivotLine[column];
            determinant = determinant * pivotValue % modulus;
            long inverse = power(pivotValue, modulus - 2, modulus);
            for (int row = column + 1; row < size; row++) {
                long[] line = values[row];
                if (line[column] == 0) {
                    continue;
                }
                long factor = line[column] * inverse % modulus;
                for (int target = column + 1; target < size; target++) {
                    long value = line[target] - factor * pivotLine[target] % modulus;
                    if (value < 0) {
                        value += modulus;
                    }
                    line[target] = value;
                }
                line[column] = 0;
            }
        }
        return determinant;
    }

    static boolean isUnimodular(long[][] matrix) {
        int needed = (ROW_BOUND_BITS * matrix.length + PRIME_BITS) / PRIME_BITS;
        int sign = 0;
        for (int index = 0; index < needed; index++) {
            long modulus = PRIMES[index];
            long determinant = determinantModulo(matrix, modulus);
            int current = determinant == 1 ? 1 : determinant == modulus - 1 ? -1 : 0;
            if (current == 0 || (sign != 0 && sign != current)) {
                return false;
            }
            sign = current;
        }
        return true;
    }

    private static final class Input {
        final BufferedInputStream stream = new BufferedInputStream(System.in);

        int next() throws IOException {
            int current;
            do {
                current = stream.read();
            } while (current <= ' ');
            int sign = 1;
            if (current == '-') {
                sign = -1;
                current = stream.read();
            }
            int value = 0;
            while (current > ' ') {
                value = value * 10 + current - '0';
                current = stream.read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        Input input = new Input();
        int size = input.next();
        long[][] matrix = new long[size][size];
        for (long[] row : matrix) {
            for (int column = 0; column < size; column++) {
                row[column] = input.next();
            }
        }
        System.out.println(isUnimodular(matrix) ? "Death" : "Power of magic saves lives");
    }
}
